export const translateDBText = (text, lang) => {
  if (!text || !lang || lang === 'en') return text;
  const clean = String(text).trim();
  
  if (dictionary[clean] && dictionary[clean][lang]) {
    return dictionary[clean][lang];
  }

  // Handle strings with dynamic numbers, dates, e.g. "15th Installment released on 28th Feb 2024"
  if (clean.includes("Installment released on")) {
    const parts = clean.split("released on");
    const instNumber = parts[0].trim(); // e.g. "15th" or "15"
    const date = parts[1].trim(); // e.g. "28th Feb 2024"
    if (lang === 'hi') return `${instNumber} किस्त ${date} को जारी की गई`;
    if (lang === 'mr') return `${instNumber} हप्ता ${date} रोजी वितरित केला गेला`;
    if (lang === 'bn') return `${instNumber} কিস্তি ${date} তারিখে প্রকাশ করা হয়েছে`;
    if (lang === 'gu') return `${instNumber} હપ્તો ${date} ના રોજ બહાર પાડવામાં આવ્યો`;
    if (lang === 'ta') return `${instNumber} தவணை ${date} அன்று வெளியிடப்பட்டது`;
    if (lang === 'te') return `${instNumber} వాయిదా ${date} న విడుదల చేయబడింది`;
    if (lang === 'kn') return `${instNumber} ಕಂತು ${date} ರಂದು ಬಿಡುಗಡೆಯಾಗಿದೆ`;
  }

  // Handle generic "Farmer 123"
  if (clean.startsWith("Farmer ")) {
    const farmerId = clean.replace("Farmer ", "");
    if (lang === 'hi') return `किसान ${farmerId}`;
    if (lang === 'mr') return `शेतकरी ${farmerId}`;
    if (lang === 'bn') return `কৃষক ${farmerId}`;
    if (lang === 'gu') return `ખેડૂત ${farmerId}`;
    if (lang === 'ta') return `விவசாயி ${farmerId}`;
    if (lang === 'te') return `రైతు ${farmerId}`;
    if (lang === 'kn') return `ರೈತ ${farmerId}`;
  }

  // Fallback to dictionary keys found inside text (e.g. for composite names)
  for (let key in dictionary) {
    if (clean.toLowerCase() === key.toLowerCase()) {
      return dictionary[key][lang];
    }
  }

  return text;
};
